139	func printMigrateCompletion(out io.Writer, result *migrateResult) {
140		if result.total == 0 {
141			fmt.Fprintln(out, "Nothing to migrate: no v1 checkpoints found")
142			fmt.Fprintln(out)
143			return
144		}
145	
146		fmt.Fprintf(out, "Migration complete: %d migrated, %d skipped, %d failed\n",
147			result.migrated, result.skipped, result.failed)
148	
149		if result.hasLoggedDetails() {
150			fmt.Fprintf(out, "Details for skipped, missing, incomplete, or failed checkpoints were logged to %s.\n", migrationLogFile)
151		}
152	
153		fmt.Fprintln(out)
154	}
