289	func sortMigratableCheckpoints(checkpoints []checkpoint.CommittedInfo) {
290		sort.SliceStable(checkpoints, func(i, j int) bool {
291			left := checkpoints[i].CreatedAt
292			right := checkpoints[j].CreatedAt
293			switch {
294			case left.IsZero() && right.IsZero():
295				return checkpoints[i].CheckpointID.String() < checkpoints[j].CheckpointID.String()
296			case left.IsZero():
297				return false
298			case right.IsZero():
299				return true
300			case left.Equal(right):
301				return checkpoints[i].CheckpointID.String() < checkpoints[j].CheckpointID.String()
302			default:
303				return left.Before(right)
304			}
305		})
306	}
