313	func migrateOneCheckpoint(ctx context.Context, repo *git.Repository, v1Store *checkpoint.GitStore, v2Store *checkpoint.V2GitStore, info checkpoint.CommittedInfo, force bool, fullArtifacts checkpoint.FullSessionArtifactsIndex) (*migratedFullCheckpoint, migrateCheckpointOutcome, error) {
314		var outcome migrateCheckpointOutcome
315	
316		existing, err := v2Store.ReadCommitted(ctx, info.CheckpointID)
317		if err != nil {
318			return nil, outcome, fmt.Errorf("failed to check v2 for checkpoint %s: %w", info.CheckpointID, err)
319		}
320	
321		if existing != nil && !force {
322			// Already in v2. Pack sessions whose /full/* artifacts are missing
323			// (resume an interrupted run) and backfill transcript.jsonl on /main
324			// where it's missing. With nothing to do on either front, return
325			// errAlreadyMigrated so the caller counts it as skipped.
326			fullCheckpoint, err := collectMissingFullCheckpointForPacking(ctx, repo, v1Store, v2Store, info, existing, fullArtifacts)
327			if err != nil && !errors.Is(err, errAlreadyMigrated) {
328				return nil, outcome, err
329			}
330			backfilled, backfillErr := backfillCompactTranscripts(ctx, v1Store, v2Store, info, existing)
331			if errors.Is(backfillErr, errTranscriptNotGeneratable) {
332				outcome.compactTranscriptSkipped = true
333			} else if backfillErr != nil && !errors.Is(backfillErr, errAlreadyMigrated) {
334				return nil, outcome, backfillErr
335			}
336			if fullCheckpoint == nil {
337				if backfilled > 0 {
338					return nil, outcome, nil
339				}
340				return nil, outcome, errAlreadyMigrated
341			}
342			return fullCheckpoint, outcome, nil
343		}
344	
345		if existing != nil && force {
346			if pruneErr := pruneV2CheckpointForForce(ctx, repo, v2Store, info.CheckpointID); pruneErr != nil {
347				return nil, outcome, fmt.Errorf("failed to reset existing v2 checkpoint %s before force migration: %w", info.CheckpointID, pruneErr)
348			}
349		}
350	
351		summary, err := v1Store.ReadCommitted(ctx, info.CheckpointID)
352		if err != nil {
353			return nil, outcome, fmt.Errorf("failed to read v1 summary: %w", err)
354		}
355		if summary == nil {
356			return nil, outcome, fmt.Errorf("v1 checkpoint %s has no summary", info.CheckpointID)
357		}
358	
359		compactFailed := false
360		shouldCopyTaskMetadata := false
361		skippedMissingSessions := 0
362		migratedSessions := 0
363		v1ToV2SessionIdx := make(map[int]int, len(summary.Sessions))
364		fullCheckpoint := &migratedFullCheckpoint{
365			checkpointID: info.CheckpointID,
366		}
367	
368		for sessionIdx := range len(summary.Sessions) {
369			content, skipped, readErr := readV1SessionForMigration(ctx, v1Store, info.CheckpointID, sessionIdx)
370			if skipped {
371				skippedMissingSessions++
372				outcome.missingSessions++
373				continue
374			}
375			if readErr != nil {
376				return nil, outcome, fmt.Errorf("failed to read v1 session %d: %w", sessionIdx, readErr)
377			}
378			if content.Metadata.IsTask {
379				shouldCopyTaskMetadata = true
380			}
381	
382			opts := buildMigrateWriteOpts(content, info, summary.CombinedAttribution)
383	
384			compacted := tryCompactTranscript(ctx, content.Transcript, content.Metadata)
385			if compacted != nil {
386				opts.CompactTranscript = compacted
387				opts.CompactTranscriptStart = computeCompactOffset(ctx, content.Transcript, compacted, content.Metadata)
388			} else if len(content.Transcript) > 0 {
389				compactFailed = true
390			}
391	
392			mainOpts := opts
393			mainOpts.Transcript = redact.AlreadyRedacted(nil)
394			v2SessionIdx, writeErr := v2Store.WriteCommittedWithSessionIndex(ctx, mainOpts)
395			if writeErr != nil {
396				return nil, outcome, fmt.Errorf("failed to write v2 session %d: %w", sessionIdx, writeErr)
397			}
398			v1ToV2SessionIdx[sessionIdx] = v2SessionIdx
399			fullCheckpoint.sessions = append(fullCheckpoint.sessions, migratedFullSession{
400				sessionIndex: v2SessionIdx,
401				content:      content,
402			})
403			migratedSessions++
404		}
405	
406		if migratedSessions == 0 {
407			return nil, outcome, fmt.Errorf("%w: v1 metadata lists %d session(s), but no transcript/session content exists for any of them", errNoMigratableSessions, len(summary.Sessions))
408		}
409	
410		if shouldCopyTaskMetadata {
411			taskTrees, taskErr := collectTaskMetadataForMigratedFullGeneration(repo, info.CheckpointID, summary, v1ToV2SessionIdx)
412			if taskErr != nil {
413				logging.Warn(ctx, "failed to copy task metadata to v2",
414					slog.String("checkpoint_id", string(info.CheckpointID)),
415					slog.String("error", taskErr.Error()),
416				)
417			} else {
418				fullCheckpoint.taskTrees = taskTrees
419			}
420		}
421	
422		if compactFailed {
423			outcome.compactTranscriptSkipped = true
424			logging.Warn(ctx, "compact transcript not generated during checkpoint migration",
425				slog.String("checkpoint_id", string(info.CheckpointID)),
426				slog.Int("migrated_sessions", migratedSessions),
427			)
428		}
429		if skippedMissingSessions > 0 {
430			logging.Warn(ctx, "checkpoint migration skipped v1 sessions with missing transcript/session content",
431				slog.String("checkpoint_id", string(info.CheckpointID)),
432				slog.Int("missing_sessions", skippedMissingSessions),
433			)
434		}
435	
436		return fullCheckpoint, outcome, nil
437	}
