439	// generationPacker buffers up to batchSize migrated checkpoints and flushes
440	// them into a single archived /full/<n> ref each time the buffer fills, so
441	// peak heap stays bounded by one batch worth of transcripts instead of
442	// growing with the total v1 list. The next generation number is resolved
443	// lazily on first flush so force-migration prune steps that remove existing
444	// archived refs are visible before we pick the next slot.
445	type generationPacker struct {
446		repo           *git.Repository
447		v2Store        *checkpoint.V2GitStore
448		batchSize      int
449		nextGeneration int
450		numbered       bool
451		pending        []migratedFullCheckpoint
452		flushed        bool
453		// writtenRefs records every /full/<n> ref this packer creates so the
454		// caller can exclude them from the generation-metadata repair pass.
455		writtenRefs []plumbing.ReferenceName
456	}
457	
458	func newGenerationPacker(repo *git.Repository, v2Store *checkpoint.V2GitStore) *generationPacker {
459		batchSize := migrateMaxCheckpointsPerGeneration
460		if batchSize <= 0 {
461			batchSize = checkpoint.DefaultMaxCheckpointsPerGeneration
462		}
463		return &generationPacker{
464			repo:      repo,
465			v2Store:   v2Store,
466			batchSize: batchSize,
467		}
468	}
469	
470	func (p *generationPacker) add(ctx context.Context, cp migratedFullCheckpoint) error {
471		p.pending = append(p.pending, cp)
472		if len(p.pending) >= p.batchSize {
473			return p.flush(ctx)
474		}
475		return nil
476	}
477	
478	func (p *generationPacker) flush(ctx context.Context) error {
479		if len(p.pending) == 0 {
480			return nil
481		}
482		if !p.numbered {
483			next, err := p.v2Store.NextGenerationNumber()
484			if err != nil {
485				return fmt.Errorf("list archived v2 generations: %w", err)
486			}
487			p.nextGeneration = next
488			p.numbered = true
489		}
490		refName := plumbing.ReferenceName(fmt.Sprintf("%s%013d", paths.V2FullRefPrefix, p.nextGeneration))
491		if err := writeMigratedFullGeneration(ctx, p.repo, refName, p.pending); err != nil {
492			return err
493		}
494		p.writtenRefs = append(p.writtenRefs, refName)
495		p.nextGeneration++
496		p.pending = nil
497		p.flushed = true
498		return nil
499	}
500	
501	func (p *generationPacker) finalize(ctx context.Context, ensureEmptyCurrent bool) error {
502		if err := p.flush(ctx); err != nil {
503			return err
504		}
505		if p.flushed && ensureEmptyCurrent {
506			return ensureEmptyV2FullCurrent(ctx, p.repo)
507		}
508		return nil
509	}
