511	func writeMigratedFullGeneration(ctx context.Context, repo *git.Repository, refName plumbing.ReferenceName, checkpoints []migratedFullCheckpoint) error {
512		entries := make(map[string]object.TreeEntry)
513	
514		for _, cp := range checkpoints {
515			for _, session := range cp.sessions {
516				if err := writeMigratedFullSessionEntries(ctx, repo, cp, session, entries); err != nil {
517					return fmt.Errorf("write full session entries for checkpoint %s session %d: %w", cp.checkpointID, session.sessionIndex, err)
518				}
519			}
520		}
521	
522		treeHash, err := checkpoint.BuildTreeFromEntries(ctx, repo, entries)
523		if err != nil {
524			return fmt.Errorf("build migrated generation tree: %w", err)
525		}
526	
527		v2Store := checkpoint.NewV2GitStore(repo, migrateRemoteName)
528		// Reuse the transcripts already in memory rather than walking the tree
529		// we just built — same first/last-event range, no redundant blob reads.
530		gen, found := checkpoint.AggregateTranscriptTimestamps(migratedTranscripts(checkpoints))
531		if !found {
532			var err error
533			gen, found, err = v2Store.ComputeGenerationCheckpointTimestamps(treeHash)
534			if err != nil {
535				return fmt.Errorf("compute checkpoint timestamps: %w", err)
536			}
537		}
538		if !found {
539			gen, found = generationMetadataFromMigratedSessions(checkpoints)
540		}
541		if !found {
542			return fmt.Errorf("no timestamps found for migrated generation %s", refName)
543		}
544	
545		treeHash, err = v2Store.AddGenerationJSONToTree(treeHash, gen)
546		if err != nil {
547			return fmt.Errorf("add generation metadata: %w", err)
548		}
549	
550		commitHash, err := checkpoint.CreateCommit(ctx, repo, treeHash, plumbing.ZeroHash,
551			fmt.Sprintf("Archive migrated generation: %s\n", refName),
552			migrateAuthorName, migrateAuthorEmail)
553		if err != nil {
554			return fmt.Errorf("create migrated generation commit: %w", err)
555		}
556	
557		if err := repo.Storer.SetReference(plumbing.NewHashReference(refName, commitHash)); err != nil {
558			return fmt.Errorf("update migrated generation ref %s: %w", refName, err)
559		}
560		return nil
561	}
