563	func migratedTranscripts(checkpoints []migratedFullCheckpoint) [][]byte {
564		var transcripts [][]byte
565		for _, cp := range checkpoints {
566			for _, session := range cp.sessions {
567				if len(session.content.Transcript) == 0 {
568					continue
569				}
570				transcripts = append(transcripts, session.content.Transcript)
571			}
572		}
573		return transcripts
