587	func writeMigratedFullSessionEntries(ctx context.Context, repo *git.Repository, cp migratedFullCheckpoint, session migratedFullSession, entries map[string]object.TreeEntry) error {
588		sessionPath := fmt.Sprintf("%s/%d/", cp.checkpointID.Path(), session.sessionIndex)
589		transcript := session.content.Transcript
590	
591		chunks, err := agent.ChunkTranscript(ctx, transcript, session.content.Metadata.Agent)
592		if err != nil {
593			return fmt.Errorf("chunk transcript: %w", err)
594		}
595		for i, chunk := range chunks {
596			blobHash, blobErr := checkpoint.CreateBlobFromContent(repo, chunk)
597			if blobErr != nil {
598				return fmt.Errorf("create transcript blob: %w", blobErr)
599			}
600			path := sessionPath + agent.ChunkFileName(paths.V2RawTranscriptFileName, i)
601			entries[path] = object.TreeEntry{
602				Name: path,
603				Mode: filemode.Regular,
604				Hash: blobHash,
605			}
606		}
607	
608		hashPath := sessionPath + paths.V2RawTranscriptHashFileName
609		contentHash := fmt.Sprintf("sha256:%x", sha256.Sum256(transcript))
610		hashBlob, err := checkpoint.CreateBlobFromContent(repo, []byte(contentHash))
611		if err != nil {
612			return fmt.Errorf("create transcript hash blob: %w", err)
613		}
614		entries[hashPath] = object.TreeEntry{
615			Name: hashPath,
616			Mode: filemode.Regular,
617			Hash: hashBlob,
618		}
619	
620		for _, taskTreeHash := range cp.taskTrees[session.sessionIndex] {
621			taskTree, treeErr := repo.TreeObject(taskTreeHash)
622			if treeErr != nil {
623				return fmt.Errorf("read task metadata tree: %w", treeErr)
624			}
625			taskEntries := make(map[string]object.TreeEntry)
626			if flattenErr := checkpoint.FlattenTree(repo, taskTree, sessionPath+"tasks", taskEntries); flattenErr != nil {
627				return fmt.Errorf("flatten task metadata tree: %w", flattenErr)
628			}
629			for path, entry := range taskEntries {
630				if _, exists := entries[path]; exists {
631					continue
632				}
633				entries[path] = entry
634			}
635		}
636	
637		return nil
638	}
