708	func pruneV2CheckpointRef(ctx context.Context, repo *git.Repository, v2Store *checkpoint.V2GitStore, refName plumbing.ReferenceName, cpID id.CheckpointID) error {
709		parentHash, rootTreeHash, err := v2Store.GetRefState(refName)
710		if err != nil {
711			if errors.Is(err, plumbing.ErrReferenceNotFound) {
712				return nil
713			}
714			return fmt.Errorf("failed to get v2 ref state for %s: %w", refName, err)
715		}
716	
717		rootTree, err := repo.TreeObject(rootTreeHash)
718		if err != nil {
719			return fmt.Errorf("failed to read v2 tree for %s: %w", refName, err)
720		}
721		if _, err := rootTree.Tree(cpID.Path()); err != nil {
722			return nil //nolint:nilerr // Checkpoint is absent from this ref, so there is nothing to prune.
723		}
724	
725		shardPrefix := string(cpID[:2])
726		shardSuffix := string(cpID[2:])
727		newRoot, err := pruneCheckpointFromRoot(repo, rootTreeHash, shardPrefix, shardSuffix)
728		if err != nil {
729			return fmt.Errorf("failed to remove checkpoint subtree from %s: %w", refName, err)
730		}
731		if newRoot == rootTreeHash {
732			return nil
733		}
734	
735		commitHash, err := checkpoint.CreateCommit(ctx, repo, newRoot, parentHash,
736			fmt.Sprintf("Reset checkpoint before force migration: %s\n", cpID),
737			migrateAuthorName, migrateAuthorEmail)
738		if err != nil {
739			return fmt.Errorf("failed to create v2 prune commit for %s: %w", refName, err)
740		}
741	
742		if err := repo.Storer.SetReference(plumbing.NewHashReference(refName, commitHash)); err != nil {
743			return fmt.Errorf("failed to update ref %s: %w", refName, err)
744		}
745		return nil
746	}
