748	func pruneV2ArchivedCheckpointRef(ctx context.Context, repo *git.Repository, v2Store *checkpoint.V2GitStore, refName plumbing.ReferenceName, cpID id.CheckpointID) error {
749		parentHash, rootTreeHash, err := v2Store.GetRefState(refName)
750		if err != nil {
751			if errors.Is(err, plumbing.ErrReferenceNotFound) {
752				return nil
753			}
754			return fmt.Errorf("failed to get v2 ref state for %s: %w", refName, err)
755		}
756	
757		rootTree, err := repo.TreeObject(rootTreeHash)
758		if err != nil {
759			return fmt.Errorf("failed to read v2 tree for %s: %w", refName, err)
760		}
761		if _, err := rootTree.Tree(cpID.Path()); err != nil {
762			return nil //nolint:nilerr // Checkpoint is absent from this ref, so there is nothing to prune.
763		}
764	
765		shardPrefix := string(cpID[:2])
766		shardSuffix := string(cpID[2:])
767		newRoot, err := pruneCheckpointFromRoot(repo, rootTreeHash, shardPrefix, shardSuffix)
768		if err != nil {
769			return fmt.Errorf("failed to remove checkpoint subtree from %s: %w", refName, err)
770		}
771		if newRoot == rootTreeHash {
772			return nil
773		}
774	
775		count, err := v2Store.CountCheckpointsInTree(newRoot)
776		if err != nil {
777			return fmt.Errorf("failed to count checkpoints in pruned %s: %w", refName, err)
778		}
779		if count == 0 {
780			if err := repo.Storer.RemoveReference(refName); err != nil {
781				return fmt.Errorf("failed to remove empty archived v2 generation %s: %w", refName, err)
782			}
783			return nil
784		}
785	
786		newRoot, err = addRecomputedGenerationJSON(v2Store, newRoot)
787		if err != nil {
788			return fmt.Errorf("failed to recompute generation metadata for %s: %w", refName, err)
789		}
790	
791		commitHash, err := checkpoint.CreateCommit(ctx, repo, newRoot, parentHash,
792			fmt.Sprintf("Reset checkpoint before force migration: %s\n", cpID),
793			migrateAuthorName, migrateAuthorEmail)
794		if err != nil {
795			return fmt.Errorf("failed to create v2 prune commit for %s: %w", refName, err)
796		}
797	
798		if err := repo.Storer.SetReference(plumbing.NewHashReference(refName, commitHash)); err != nil {
799			return fmt.Errorf("failed to update ref %s: %w", refName, err)
800		}
801		return nil
802	}
