804	func addRecomputedGenerationJSON(v2Store *checkpoint.V2GitStore, treeHash plumbing.Hash) (plumbing.Hash, error) {
805		gen, found, err := v2Store.ComputeGenerationTimestampsFromTrees(treeHash, nil)
806		if err != nil {
807			return plumbing.ZeroHash, fmt.Errorf("compute raw transcript timestamps: %w", err)
808		}
809		if !found {
810			gen, found, err = v2Store.ComputeGenerationCheckpointTimestamps(treeHash)
811			if err != nil {
812				return plumbing.ZeroHash, fmt.Errorf("compute checkpoint timestamps: %w", err)
813			}
814		}
815		if !found {
816			return treeHash, nil
817		}
818	
819		newTreeHash, err := v2Store.AddGenerationJSONToTree(treeHash, gen)
820		if err != nil {
821			return plumbing.ZeroHash, fmt.Errorf("add generation metadata: %w", err)
822		}
823		return newTreeHash, nil
824	}
