826	func pruneCheckpointFromRoot(repo *git.Repository, rootTreeHash plumbing.Hash, shardPrefix, shardSuffix string) (plumbing.Hash, error) {
827		newRoot, err := checkpoint.UpdateSubtree(repo, rootTreeHash,
828			[]string{shardPrefix},
829			nil,
830			checkpoint.UpdateSubtreeOptions{
831				MergeMode:   checkpoint.MergeKeepExisting,
832				DeleteNames: []string{shardSuffix},
833			},
834		)
835		if err != nil {
836			return plumbing.ZeroHash, fmt.Errorf("failed to prune checkpoint from shard: %w", err)
837		}
838		if newRoot == rootTreeHash {
839			return newRoot, nil
840		}
841	
842		newRootTree, err := repo.TreeObject(newRoot)
843		if err != nil {
844			return plumbing.ZeroHash, fmt.Errorf("failed to read pruned root tree: %w", err)
845		}
846		shardTree, err := newRootTree.Tree(shardPrefix)
847		if err != nil {
848			return newRoot, nil //nolint:nilerr // The shard prefix was already absent after pruning.
849		}
850		if len(shardTree.Entries) > 0 {
851			return newRoot, nil
852		}
853	
854		prunedRoot, err := checkpoint.UpdateSubtree(repo, rootTreeHash,
855			nil,
856			nil,
857			checkpoint.UpdateSubtreeOptions{
858				MergeMode:   checkpoint.MergeKeepExisting,
859				DeleteNames: []string{shardPrefix},
860			},
861		)
862		if err != nil {
863			return plumbing.ZeroHash, fmt.Errorf("failed to prune empty shard prefix: %w", err)
864		}
865		return prunedRoot, nil
866	}
