907	func compactTranscriptForStartLine(ctx context.Context, transcript []byte, m checkpoint.CommittedMetadata, startLine int) []byte {
908		if len(transcript) == 0 {
909			return nil
910		}
911		if m.Agent == "" {
912			logging.Warn(ctx, "compact transcript skipped: no agent type in checkpoint metadata",
913				slog.String("checkpoint_id", string(m.CheckpointID)),
914			)
915			return nil
916		}
917	
918		compacted, err := compact.Compact(redact.AlreadyRedacted(transcript), compact.MetadataFields{
919			Agent:      string(m.Agent),
920			CLIVersion: versioninfo.Version,
921			StartLine:  startLine,
922		})
923		if err != nil {
924			logging.Warn(ctx, "compact transcript generation failed during migration",
925				slog.String("checkpoint_id", string(m.CheckpointID)),
926				slog.String("agent", string(m.Agent)),
927				slog.String("error", err.Error()),
928			)
929			return nil
930		}
931		if len(compacted) == 0 {
932			logging.Warn(ctx, "transcript.jsonl generation produced no output",
933				slog.String("checkpoint_id", string(m.CheckpointID)),
934				slog.String("agent", string(m.Agent)),
935				slog.Int("input_bytes", len(transcript)),
936			)
937			return nil
938		}
939		return compacted
940	}
