942	// computeCompactOffset determines the transcript.jsonl line offset for a checkpoint
943	// by comparing a full compact (startLine=0) against the scoped compact. The difference
944	// is the number of compact lines before this checkpoint's data.
945	func computeCompactOffset(ctx context.Context, fullTranscript, fullCompact []byte, m checkpoint.CommittedMetadata) int {
946		startLine := m.GetTranscriptStart()
947		if startLine == 0 || len(fullTranscript) == 0 || m.Agent == "" {
948			return 0
949		}
950	
951		if len(fullCompact) == 0 {
952			return 0
953		}
954	
955		scopedCompact, err := compact.Compact(redact.AlreadyRedacted(fullTranscript), compact.MetadataFields{
956			Agent:      string(m.Agent),
957			CLIVersion: versioninfo.Version,
958			StartLine:  startLine,
959		})
960		if err != nil {
961			logging.Warn(ctx, "compact transcript offset calculation failed during migration",
962				slog.String("checkpoint_id", string(m.CheckpointID)),
963				slog.String("agent", string(m.Agent)),
964				slog.String("error", err.Error()),
965			)
966			return 0
967		}
968		if len(scopedCompact) == 0 {
969			return 0
970		}
971	
972		fullLines := bytes.Count(fullCompact, []byte{'\n'})
973		scopedLines := bytes.Count(scopedCompact, []byte{'\n'})
974		offset := fullLines - scopedLines
975		if offset < 0 {
976			logging.Warn(ctx, "compact transcript offset was negative during migration, defaulting to 0",
977				slog.String("checkpoint_id", string(m.CheckpointID)),
978				slog.Int("full_lines", fullLines),
979				slog.Int("scoped_lines", scopedLines),
980			)
981			return 0
982		}
983		return offset
984	}
