990	
991	func collectTaskMetadataForMigratedFullGenerationWithRootSession(
992		repo *git.Repository,
993		cpID id.CheckpointID,
994		summary *checkpoint.CheckpointSummary,
995		v1ToV2SessionIdx map[int]int,
996		rootTaskV2SessionIdx int,
997		attachRootTasks bool,
998	) (map[int][]plumbing.Hash, error) {
999		v1Tree, err := resolveV1CheckpointTree(repo, cpID)
1000		if err != nil {
1001			return nil, err
1002		}
1003	
1004		taskTrees := make(map[int][]plumbing.Hash)
1005	
1006		// Legacy v1 layout stores task metadata at checkpoint root: <cp>/tasks/<tool-use-id>/...
1007		// Prefer attaching this tree to the latest session in v2.
1008		if rootTasksTree, rootTasksErr := v1Tree.Tree("tasks"); rootTasksErr == nil {
1009			if attachRootTasks {
1010				taskTrees[rootTaskV2SessionIdx] = append(taskTrees[rootTaskV2SessionIdx], rootTasksTree.Hash)
1011			}
1012		}
1013	
1014		for sessionIdx := range len(summary.Sessions) {
1015			sessionDir := strconv.Itoa(sessionIdx)
1016			sessionTree, sessionErr := v1Tree.Tree(sessionDir)
1017			if sessionErr != nil {
1018				continue
1019			}
1020	
1021			tasksTree, tasksErr := sessionTree.Tree("tasks")
1022			if tasksErr != nil {
1023				continue
1024			}
1025	
1026			v2SessionIdx, ok := v1ToV2SessionIdx[sessionIdx]
1027			if !ok {
1028				continue
1029			}
1030			taskTrees[v2SessionIdx] = append(taskTrees[v2SessionIdx], tasksTree.Hash)
1031		}
1032	
1033		return taskTrees, nil
1034	}
1035	
1036	func latestMigratedV2SessionIndex(v1ToV2SessionIdx map[int]int) (int, bool) {
1037		latest := -1
1038		for _, v2SessionIdx := range v1ToV2SessionIdx {
1039			if v2SessionIdx > latest {
1040				latest = v2SessionIdx
1041			}
1042		}
1043		if latest < 0 {
1044			return -1, false
1045		}
1046		return latest, true
1047	}
