1049	func resolveV1CheckpointTree(repo *git.Repository, cpID id.CheckpointID) (*object.Tree, error) {
1050		refName := plumbing.NewBranchReferenceName(paths.MetadataBranchName)
1051		ref, err := repo.Reference(refName, true)
1052		if err != nil {
1053			// Try remote tracking branch
1054			remoteRefName := plumbing.NewRemoteReferenceName(migrateRemoteName, paths.MetadataBranchName)
1055			ref, err = repo.Reference(remoteRefName, true)
1056			if err != nil {
1057				return nil, fmt.Errorf("v1 branch not found: %w", err)
1058			}
1059		}
1060	
1061		commit, err := repo.CommitObject(ref.Hash())
1062		if err != nil {
1063			return nil, fmt.Errorf("failed to get v1 commit: %w", err)
1064		}
1065	
1066		rootTree, err := commit.Tree()
1067		if err != nil {
1068			return nil, fmt.Errorf("failed to get v1 tree: %w", err)
1069		}
1070	
1071		cpTree, err := rootTree.Tree(cpID.Path())
1072		if err != nil {
1073			return nil, fmt.Errorf("checkpoint %s not found in v1 tree: %w", cpID, err)
1074		}
1075	
1076		return cpTree, nil
1077	}
