1079	// collectMissingFullCheckpointForPacking returns a migratedFullCheckpoint
1080	// scoped to the sessions that lack /full/* artifacts on this v2 checkpoint,
1081	// reading their content from v1 so the caller can hand it to the same
1082	// generationPacker fresh migrations use. Returns errAlreadyMigrated when
1083	// every session is already packed.
1084	func collectMissingFullCheckpointForPacking(
1085		ctx context.Context,
1086		repo *git.Repository,
1087		v1Store *checkpoint.GitStore,
1088		v2Store *checkpoint.V2GitStore,
1089		info checkpoint.CommittedInfo,
1090		v2Summary *checkpoint.CheckpointSummary,
1091		fullArtifacts checkpoint.FullSessionArtifactsIndex,
1092	) (*migratedFullCheckpoint, error) {
1093		missingSessions, err := collectMissingFullSessionsForPacking(ctx, v2Store, info.CheckpointID, v2Summary, fullArtifacts)
1094		if err != nil {
1095			return nil, err
1096		}
1097		if len(missingSessions) == 0 {
1098			return nil, errAlreadyMigrated
1099		}
1100	
1101		v1Summary, err := v1Store.ReadCommitted(ctx, info.CheckpointID)
1102		if err != nil {
1103			return nil, fmt.Errorf("failed to read v1 summary while resuming v2 migration: %w", err)
1104		}
1105		if v1Summary == nil {
1106			return nil, fmt.Errorf("v1 checkpoint %s has no summary", info.CheckpointID)
1107		}
1108	
1109		v1BySessionID, err := collectV1SessionIndexesForPacking(ctx, v1Store, info.CheckpointID, v1Summary, missingSessions)
1110		if err != nil {
1111			return nil, err
1112		}
1113	
1114		fullCheckpoint := &migratedFullCheckpoint{
1115			checkpointID: info.CheckpointID,
1116		}
1117		v1ToV2SessionIdx := make(map[int]int)
1118	
1119		for _, missingSession := range missingSessions {
1120			v1Session, ok, readErr := readV1SessionForMissingFullArtifact(ctx, v1Store, info.CheckpointID, v1Summary, v1BySessionID, missingSession)
1121			if readErr != nil {
1122				return nil, readErr
1123			}
1124			if !ok {
1125				return nil, fmt.Errorf("failed to find v1 session for v2 session %d while resuming migration", missingSession.sessionIndex)
1126			}
1127	
1128			fullCheckpoint.sessions = append(fullCheckpoint.sessions, migratedFullSession{
1129				sessionIndex: missingSession.sessionIndex,
1130				content:      v1Session.content,
1131			})
1132			v1ToV2SessionIdx[v1Session.sessionIndex] = missingSession.sessionIndex
1133		}
