1162	func collectMissingFullSessionsForPacking(
1163		ctx context.Context,
1164		v2Store *checkpoint.V2GitStore,
1165		checkpointID id.CheckpointID,
1166		summary *checkpoint.CheckpointSummary,
1167		fullArtifacts checkpoint.FullSessionArtifactsIndex,
1168	) ([]missingFullSessionForPacking, error) {
1169		missingSessions := make([]missingFullSessionForPacking, 0)
1170		for sessionIdx := range len(summary.Sessions) {
1171			// Production passes a pre-built index; nil falls back to the per-call
1172			// predicate for tests that exercise this helper directly.
1173			var ok bool
1174			if fullArtifacts != nil {
1175				ok = fullArtifacts.Has(checkpointID, sessionIdx)
1176			} else {
1177				var checkErr error
1178				ok, checkErr = v2Store.HasFullSessionArtifacts(checkpointID, sessionIdx)
1179				if checkErr != nil {
1180					return nil, fmt.Errorf("failed to check v2 session %d artifacts: %w", sessionIdx, checkErr)
1181				}
1182			}
1183			if ok {
1184				continue
1185			}
1186	
1187			// Metadata-only read: only SessionID is needed downstream.
1188			meta, readErr := v2Store.ReadSessionMetadata(ctx, checkpointID, sessionIdx)
1189			if readErr != nil {
1190				return nil, fmt.Errorf("failed to read v2 session %d metadata while resuming migration: %w", sessionIdx, readErr)
1191			}
1192	
1193			missingSessions = append(missingSessions, missingFullSessionForPacking{
1194				sessionIndex: sessionIdx,
1195				sessionID:    meta.SessionID,
1196			})
1197		}
1198	
1199		return missingSessions, nil
1200	}
