1202	// collectV1SessionIndexesForPacking maps each missing session's id to its v1
1203	// session index. Resolving by session_id is necessary because v1/v2 indices
1204	// can drift — v1 sessions without a transcript are skipped on fresh migration.
1205	func collectV1SessionIndexesForPacking(
1206		ctx context.Context,
1207		v1Store *checkpoint.GitStore,
1208		checkpointID id.CheckpointID,
1209		summary *checkpoint.CheckpointSummary,
1210		missingSessions []missingFullSessionForPacking,
1211	) (map[string][]int, error) {
1212		neededSessionIDs := make(map[string]struct{})
1213		for _, session := range missingSessions {
1214			if session.sessionID != "" {
1215				neededSessionIDs[session.sessionID] = struct{}{}
1216			}
1217		}
1218	
1219		bySessionID := make(map[string][]int)
1220		if len(neededSessionIDs) == 0 {
1221			return bySessionID, nil
1222		}
1223	
1224		for sessionIdx := range len(summary.Sessions) {
1225			metadata, err := v1Store.ReadSessionMetadata(ctx, checkpointID, sessionIdx)
1226			if err != nil {
1227				if ctxErr := ctx.Err(); ctxErr != nil {
1228					return nil, fmt.Errorf("context canceled while reading v1 session metadata: %w", ctxErr)
1229				}
1230				continue
1231			}
1232			if _, ok := neededSessionIDs[metadata.SessionID]; ok {
1233				bySessionID[metadata.SessionID] = append(bySessionID[metadata.SessionID], sessionIdx)
1234			}
1235		}
1236	
1237		return bySessionID, nil
1238	}
1239	
1240	func readV1SessionForMissingFullArtifact(
1241		ctx context.Context,
1242		v1Store *checkpoint.GitStore,
1243		checkpointID id.CheckpointID,
1244		summary *checkpoint.CheckpointSummary,
1245		bySessionID map[string][]int,
1246		missingSession missingFullSessionForPacking,
1247	) (v1SessionForPacking, bool, error) {
1248		var triedSessionIndexes map[int]struct{}
1249		if missingSession.sessionID != "" {
1250			indexes := bySessionID[missingSession.sessionID]
1251			triedSessionIndexes = make(map[int]struct{}, len(indexes))
1252			for i := len(indexes) - 1; i >= 0; i-- {
1253				sessionIdx := indexes[i]
1254				triedSessionIndexes[sessionIdx] = struct{}{}
1255				session, found, err := readV1SessionForPacking(ctx, v1Store, checkpointID, sessionIdx)
1256				if err != nil || found {
1257					return session, found, err
1258				}
1259			}
1260		}
1261	
1262		if missingSession.sessionIndex >= len(summary.Sessions) {
1263			return v1SessionForPacking{}, false, nil
1264		}
1265		if _, tried := triedSessionIndexes[missingSession.sessionIndex]; tried {
1266			return v1SessionForPacking{}, false, nil
1267		}
1268		return readV1SessionForPacking(ctx, v1Store, checkpointID, missingSession.sessionIndex)
1269	}
1270	
1271	func readV1SessionForPacking(
1272		ctx context.Context,
1273		v1Store *checkpoint.GitStore,
1274		checkpointID id.CheckpointID,
1275		sessionIdx int,
1276	) (v1SessionForPacking, bool, error) {
1277		content, err := v1Store.ReadSessionContent(ctx, checkpointID, sessionIdx)
1278		if err != nil {
1279			if errors.Is(err, checkpoint.ErrNoTranscript) || errors.Is(err, checkpoint.ErrCheckpointNotFound) {
1280				return v1SessionForPacking{}, false, nil
1281			}
1282			return v1SessionForPacking{}, false, fmt.Errorf("failed to read v1 session %d while resuming migration: %w", sessionIdx, err)
1283		}
1284	
1285		return v1SessionForPacking{
1286			sessionIndex: sessionIdx,
1287			content:      content,
1288		}, true, nil
1289	}
