1291	func backfillCompactTranscripts(ctx context.Context, v1Store *checkpoint.GitStore, v2Store *checkpoint.V2GitStore, info checkpoint.CommittedInfo, v2Summary *checkpoint.CheckpointSummary) (int, error) {
1292		missingSessions, skippedNoAgent, err := collectMissingCompactSessionsForBackfill(ctx, v2Store, info.CheckpointID, v2Summary)
1293		if err != nil {
1294			return 0, err
1295		}
1296		if len(missingSessions) == 0 {
1297			if skippedNoAgent {
1298				return 0, fmt.Errorf("%w: no agent type in metadata", errTranscriptNotGeneratable)
1299			}
1300			return 0, errAlreadyMigrated
1301		}
1302	
1303		v1Summary, err := v1Store.ReadCommitted(ctx, info.CheckpointID)
1304		if err != nil {
1305			return 0, fmt.Errorf("failed to read v1 summary while backfilling compact transcripts: %w", err)
1306		}
1307		if v1Summary == nil {
1308			return 0, fmt.Errorf("v1 checkpoint %s has no summary", info.CheckpointID)
1309		}
1310	
1311		v1BySessionID, err := collectV1SessionIndexesForPacking(ctx, v1Store, info.CheckpointID, v1Summary, missingSessions)
1312		if err != nil {
1313			return 0, err
1314		}
1315	
1316		backfilled := 0
1317		skippedBackfill := false
1318		var lastAgent string
1319		for _, missingSession := range missingSessions {
1320			v1Session, ok, readErr := readV1SessionForMissingFullArtifact(ctx, v1Store, info.CheckpointID, v1Summary, v1BySessionID, missingSession)
1321			if readErr != nil {
1322				logging.Warn(ctx, "transcript.jsonl backfill: could not read v1 session",
1323					slog.String("checkpoint_id", string(info.CheckpointID)),
1324					slog.Int("session_index", missingSession.sessionIndex),
1325					slog.String("error", readErr.Error()),
1326				)
1327				skippedBackfill = true
1328				continue
1329			}
1330			if !ok {
1331				logging.Warn(ctx, "transcript.jsonl backfill: no matching v1 session",
1332					slog.String("checkpoint_id", string(info.CheckpointID)),
1333					slog.Int("session_index", missingSession.sessionIndex),
1334				)
1335				skippedBackfill = true
1336				continue
1337			}
1338	
1339			content := v1Session.content
1340			if content.Metadata.Agent != "" {
1341				lastAgent = string(content.Metadata.Agent)
1342			}
1343	
1344			compacted := tryCompactTranscript(ctx, content.Transcript, content.Metadata)
1345			if compacted == nil {
1346				if len(content.Transcript) == 0 {
1347					logging.Warn(ctx, "transcript.jsonl backfill: empty transcript in v1",
1348						slog.String("checkpoint_id", string(info.CheckpointID)),
1349						slog.Int("session_index", missingSession.sessionIndex),
1350					)
1351				}
1352				skippedBackfill = true
1353				continue
1354			}
1355	
1356			updateErr := v2Store.UpdateCommitted(ctx, checkpoint.UpdateCommittedOptions{
1357				CheckpointID:      info.CheckpointID,
1358				SessionID:         content.Metadata.SessionID,
1359				CompactTranscript: compacted,
1360			})
1361			if updateErr != nil {
1362				logging.Warn(ctx, "transcript.jsonl backfill: failed to write to v2",
1363					slog.String("checkpoint_id", string(info.CheckpointID)),
1364					slog.Int("session_index", missingSession.sessionIndex),
1365					slog.String("error", updateErr.Error()),
1366				)
1367				skippedBackfill = true
1368				continue
1369			}
1370	
1371			backfilled++
1372		}
1373	
1374		if backfilled == 0 {
1375			if lastAgent != "" {
1376				return 0, fmt.Errorf("%w: agent %q", errTranscriptNotGeneratable, lastAgent)
1377			}
1378			if skippedNoAgent {
1379				return 0, fmt.Errorf("%w: no agent type in metadata", errTranscriptNotGeneratable)
1380			}
1381			return 0, errTranscriptNotGeneratable
1382		}
1383		if skippedBackfill {
1384			if lastAgent != "" {
1385				return backfilled, fmt.Errorf("%w: agent %q", errTranscriptNotGeneratable, lastAgent)
1386			}
1387			return backfilled, errTranscriptNotGeneratable
1388		}
1389	
1390		return backfilled, nil
1391	}
1392	
1393	func collectMissingCompactSessionsForBackfill(
1394		ctx context.Context,
1395		v2Store *checkpoint.V2GitStore,
1396		checkpointID id.CheckpointID,
1397		summary *checkpoint.CheckpointSummary,
1398	) ([]missingFullSessionForPacking, bool, error) {
1399		var missingSessions []missingFullSessionForPacking
1400		skippedNoAgent := false
1401		for sessionIdx, session := range summary.Sessions {
1402			if session.Transcript != "" {
1403				continue
1404			}
1405	
1406			meta, err := v2Store.ReadSessionMetadata(ctx, checkpointID, sessionIdx)
1407			if err != nil {
1408				return nil, false, fmt.Errorf("failed to read v2 session %d metadata while backfilling compact transcript: %w", sessionIdx, err)
1409			}
1410			if meta.Agent == "" {
1411				skippedNoAgent = true
1412				continue
1413			}
1414			missingSessions = append(missingSessions, missingFullSessionForPacking{
1415				sessionIndex: sessionIdx,
1416				sessionID:    meta.SessionID,
1417			})
1418		}
1419		return missingSessions, skippedNoAgent, nil
1420	}
